#include "subscreen_data.h"
#include <iostream>
#include <stdexcept>
int main(int argc,char **argv){try{if(argc!=2)throw std::runtime_error("fixture files path required");unsigned checks=0;auto check=[&](bool b,const char *s){++checks;if(!b)throw std::runtime_error(s);};std::vector<std::array<int,4>> choices;auto no=re4::LoadOriginalPickupMessage(argv[1],0,0,0,1,true,&choices);auto yes=re4::LoadOriginalPickupMessage(argv[1],0,0,0,0,true);check(choices.size()==2,"Original Yes/No");for(const auto &r:choices){check(r[1]==179 && r[3]==203,"Original SS line19 and font24");check(r[0]<r[2],"Valid glyph choice bounds");}check(choices[0][2]<=choices[1][0],"Separate touch choices");check(no.rgba!=yes.rgba,"Original selection cursor changes");unsigned minY=384,maxY=0;for(unsigned y=0;y<384;++y)for(unsigned x=0;x<512;++x)if(no.rgba[(y*512+x)*4+3]){minY=std::min(minY,y);maxY=std::max(maxY,y);}check(minY>=160 && maxY<204,"SS text fits compact requester");for(auto d:{std::array<unsigned,2>{10,6},{11,7},{12,8},{15,8}}){auto board=re4::LoadOriginalCaseBoardImage(argv[1],d[0],d[1]);check(board.width==640 && board.height==480,"Original case models unchanged");}std::cout<<"Fix18 native menu PASS: "<<checks<<" checks\n";return 0;}catch(const std::exception &e){std::cerr<<e.what()<<"\n";return 1;}}
